"""Authored, offline interactive stories for the community feed.

These are fictional editorial situations, not posts or activity by real users.
Each role starts with 50 in trust, goal, control and eq. The engine owns state;
the option effect is the only scoring input. Effects describe this situation,
not a player's personality or a guaranteed result outside the simulation.
"""


def _option(choice_id, text, next_id, effect, explanation):
    """Keep authored effects in the canonical trust / goal / control / eq order."""
    return {
        "id": choice_id,
        "text": text,
        "next": next_id,
        "effect": dict(zip(("trust", "goal", "control", "eq"), effect)),
        "explanation": explanation,
    }


def _node(speaker, text, *options):
    return {"speaker": speaker, "text": text, "options": list(options)}


def _ending(title, text, lesson):
    return {"title": title, "text": text, "lesson": lesson}


